// 驗簽 → 取出留言事件 → 過濾。
//
// ⚠️ 留言走的是 entry[].changes[],不是 entry[].messaging[]。
//    同一個 webhook URL 兩種結構都會進來,不要假設。

const crypto = require('crypto');

const item = $input.first();
const raw = Buffer.from(item.binary.data.data, 'base64');
const signature = item.json.headers['x-hub-signature-256'];

const expected = 'sha256=' + crypto.createHmac('sha256', $env.META_APP_SECRET).update(raw).digest('hex');
const a = Buffer.from(signature ?? '');
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('X-Hub-Signature-256 驗證失敗');
}

const payload = JSON.parse(raw.toString('utf8'));
const staticData = $getWorkflowStaticData('global');
staticData.seenComments = staticData.seenComments || [];

const out = [];

for (const entry of payload.entry ?? []) {
  for (const change of entry.changes ?? []) {
    if (change.field !== 'feed') continue;

    const v = change.value ?? {};
    if (v.item !== 'comment') continue;   // 還有 post / like / reaction
    if (v.verb !== 'add') continue;        // edited / remove 不處理

    // ★ 粉專自己的留言也會觸發 webhook。不濾掉 → 自動回覆會遞迴。
    if (v.from?.id === entry.id) continue;

    if (typeof v.message !== 'string' || v.message.trim() === '') continue;

    if (staticData.seenComments.includes(v.comment_id)) continue;
    staticData.seenComments.push(v.comment_id);

    out.push({
      json: {
        commentId: v.comment_id,
        postId: v.post_id,
        fromId: v.from?.id,
        fromName: v.from?.name ?? '',
        message: v.message.trim(),
      },
    });
  }
}

staticData.seenComments = staticData.seenComments.slice(-500);
return out;

// 把後端回覆組成「公開回覆」與「私訊」兩種文案。
//
// 公開回覆要簡短（留言串裡太長很吵）,細節走私訊。

const sources = $('驗簽並取出留言').all();
const out = [];

$input.all().forEach((item, i) => {
  const src = sources[i]?.json;
  if (!src) return;

  const status = item.json.statusCode ?? 200;
  const ok = status >= 200 && status < 300;
  const reply = (ok ? item.json.body?.reply : '') || '';

  const publicText = reply.trim() === ''
    ? `${src.fromName} 您好,我們已收到您的提問,稍後由客服私訊您 🙏`
    : `${src.fromName} 您好,已私訊您完整說明 🙏`;

  out.push({
    json: {
      commentId: src.commentId,
      publicText,
      privateText: reply.trim() === '' ? '您好,我們已收到您的提問,客服稍後回覆您。' : reply.slice(0, 2000),
    },
  });
});

return out;
